"""Coupon pricing in integer cents."""
def apply_coupon(total_cents: int, percent: int) -> int:
    if type(total_cents) is not int or type(percent) is not int:
        raise ValueError('integer inputs required')
    if total_cents < 0 or not 0 <= percent <= 100:
        raise ValueError('invalid coupon input')
    return total_cents * (100 - percent) / 100

export function previewCoupon(totalCents, percent) {
  if (!Number.isSafeInteger(totalCents) || !Number.isSafeInteger(percent) || totalCents < 0 || percent < 0 || percent > 100) throw new Error('Invalid coupon input');
  return Math.floor(totalCents * (100 - percent) / 100);
}

